-- Phase 17: Internal prosecution referrals, text evidence index, and judgment execution tracking.
CREATE TABLE prosecution_referrals(id TEXT PRIMARY KEY,report_id TEXT NOT NULL UNIQUE REFERENCES police_reports(id),case_id TEXT REFERENCES court_cases(id),created_by TEXT NOT NULL REFERENCES users(id),summary TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'referred' CHECK(status IN ('referred','reviewing','filed_to_court','dismissed')),review_note TEXT NOT NULL DEFAULT '',reviewed_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE justice_evidence(id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES court_cases(id),submitted_by TEXT NOT NULL REFERENCES users(id),title TEXT NOT NULL,description TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_justice_evidence_case ON justice_evidence(case_id,created_at);
CREATE TABLE judgment_executions(id TEXT PRIMARY KEY,case_id TEXT NOT NULL UNIQUE REFERENCES court_cases(id),created_by TEXT NOT NULL REFERENCES users(id),instructions TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'opened' CHECK(status IN ('opened','in_progress','completed','suspended')),last_note TEXT NOT NULL DEFAULT '',updated_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
